char **findLongestSubarray(char **array, int arraySize, int *returnSize) {
  int *prefix = (int *)malloc(sizeof(int) * (arraySize + 1));
  prefix[0] = 0;
  for (int i = 0; i < arraySize; i++) {
    char c = array[i][0];
    int d = (c >= '0' && c <= '9') ? -1 : 1;
    prefix[i + 1] = prefix[i] + d;
  }
  int size = 2 * arraySize + 3;
  int *first = (int *)malloc(sizeof(int) * size);
  for (int i = 0; i < size; i++) first[i] = -1;
  int offset = arraySize + 1;
  int bestLen = 0, bestStart = 0;
  for (int i = 0; i <= arraySize; i++) {
    int idx = prefix[i] + offset;
    if (first[idx] == -1) {
      first[idx] = i;
    } else {
      int len = i - first[idx];
      if (len > bestLen) {
        bestLen = len;
        bestStart = first[idx];
      }
    }
  }
  char **res = (char **)malloc(sizeof(char *) * (bestLen > 0 ? bestLen : 1));
  for (int i = 0; i < bestLen; i++) res[i] = array[bestStart + i];
  *returnSize = bestLen;
  free(prefix);
  free(first);
  return res;
}

class Solution {
public:
  vector<string> findLongestSubarray(vector<string> &array) {
    unordered_map<int, int> first;
    first[0] = -1;
    int sum = 0, bestLen = 0, bestStart = 0;
    for (int i = 0; i < (int)array.size(); i++) {
      char c = array[i][0];
      sum += (c >= '0' && c <= '9') ? -1 : 1;
      if (first.count(sum)) {
        int len = i - first[sum];
        if (len > bestLen) {
          bestLen = len;
          bestStart = first[sum] + 1;
        }
      } else {
        first[sum] = i;
      }
    }
    return vector<string>(array.begin() + bestStart, array.begin() + bestStart + bestLen);
  }
};

func findLongestSubarray(array []string) []string {
	first := map[int]int{0: -1}
	sum, bestLen, bestStart := 0, 0, 0
	for i := 0; i < len(array); i++ {
		c := array[i][0]
		if c >= '0' && c <= '9' {
			sum--
		} else {
			sum++
		}
		if idx, ok := first[sum]; ok {
			if i-idx > bestLen {
				bestLen = i - idx
				bestStart = idx + 1
			}
		} else {
			first[sum] = i
		}
	}
	res := []string{}
	for i := bestStart; i < bestStart+bestLen; i++ {
		res = append(res, array[i])
	}
	return res
}

class Solution {
  public String[] findLongestSubarray(String[] array) {
    Map<Integer, Integer> first = new HashMap<>();
    first.put(0, -1);
    int sum = 0, bestLen = 0, bestStart = 0;
    for (int i = 0; i < array.length; i++) {
      char c = array[i].charAt(0);
      sum += (c >= '0' && c <= '9') ? -1 : 1;
      if (first.containsKey(sum)) {
        int len = i - first.get(sum);
        if (len > bestLen) {
          bestLen = len;
          bestStart = first.get(sum) + 1;
        }
      } else {
        first.put(sum, i);
      }
    }
    List<String> res = new ArrayList<>();
    for (int i = bestStart; i < bestStart + bestLen; i++) res.add(array[i]);
    return res.toArray(new String[0]);
  }
}

class Solution:
    def findLongestSubarray(self, array: List[str]) -> List[str]:
        first = {0: -1}
        total = 0
        best_len = best_start = 0
        for i, ch in enumerate(array):
            total += -1 if ch.isdigit() else 1
            if total in first:
                if i - first[total] > best_len:
                    best_len = i - first[total]
                    best_start = first[total] + 1
            else:
                first[total] = i
        return array[best_start:best_start + best_len]

impl Solution {
  pub fn find_longest_subarray(array: Vec<String>) -> Vec<String> {
    let mut first: HashMap<i32, i32> = HashMap::new();
    first.insert(0, -1);
    let (mut sum, mut best_len, mut best_start) = (0, 0, 0);
    for (i, s) in array.iter().enumerate() {
      let c = s.as_bytes()[0];
      if c.is_ascii_digit() {
        sum -= 1;
      } else {
        sum += 1;
      }
      if let Some(&idx) = first.get(&sum) {
        if i as i32 - idx > best_len {
          best_len = i as i32 - idx;
          best_start = idx + 1;
        }
      } else {
        first.insert(sum, i as i32);
      }
    }
    array[best_start as usize..(best_start + best_len) as usize].to_vec()
  }
}

const findLongestSubarray = (array: string[]): string[] => {
  const first = new Map<number, number>();
  first.set(0, -1);
  let sum = 0;
  let bestLen = 0;
  let bestStart = 0;
  for (let i = 0; i < array.length; i++) {
    const c = array[i][0];
    sum += c >= '0' && c <= '9' ? -1 : 1;
    if (first.has(sum)) {
      const len = i - first.get(sum)!;
      if (len > bestLen) {
        bestLen = len;
        bestStart = first.get(sum)! + 1;
      }
    } else {
      first.set(sum, i);
    }
  }
  return array.slice(bestStart, bestStart + bestLen);
};
